@group(0) @binding(2)
var<storage, read_write> reduced: array<TagMonoid>;
const LG_WG_SIZE = 8u;
const WG_SIZE = 256u;
var<workgroup> sh_scratch: array<TagMonoid, WG_SIZE>;
