fn main(
    @builtin(global_invocation_id) global_id: vec3<u32>,
    @builtin(local_invocation_id) local_id: vec3<u32>,
) {
    let ix = global_id.x;
    let tag_word = scene[config.pathtag_base + ix];
    var agg = reduce_tag(tag_word);
    sh_scratch[local_id.x] = agg;
    for (var i = 0u; i < firstTrailingBit(WG_SIZE); i += 1u) {
        workgroupBarrier();
        if local_id.x + (1u << i) < WG_SIZE {
            let other = sh_scratch[local_id.x + (1u << i)];
            agg = combine_tag_monoid(agg, other);
        }
        workgroupBarrier();
        sh_scratch[local_id.x] = agg;
    }
    if local_id.x == 0u {
        let o = ix >> LG_WG_SIZE;
        reduced[o].trans_ix = agg.trans_ix;
        reduced[o].pathseg_ix = agg.pathseg_ix;
        reduced[o].pathseg_offset = agg.pathseg_offset;
        reduced[o].style_ix = agg.style_ix;
        reduced[o].path_ix = agg.path_ix;
    }
